\set ON_ERROR_STOP on
\ir hris_attendance_review_setup.sql
create function pg_temp.config_deny(q text,label text)returns void language plpgsql as $$begin begin execute q;exception when others then if sqlerrm like 'HRIS:%'or sqlstate='42501' then return;end if;raise;end;raise exception 'FAIL: % accepted',label;end$$;
set local role authenticated;
select hris_create_pay_group('Fiction existing pay group','Fiction grouping only, no new rate');
select hris_save_payroll_policy(null,'2026-10-10','{"telat_mulai_menit":1,"telat_blok_menit":5,"telat_nominal_per_blok":0,"telat_maks":0,"bolos_per_hari":0,"lembur_per_jam":100}','Fiction approved existing rate field');
select pg_temp.check_it((hris_global_payroll_policy('2026-10-09')->>'lembur_per_jam')::numeric=0,'earlier legacy default remains zero');
select pg_temp.check_it((hris_global_payroll_policy('2026-10-10')->>'lembur_per_jam')::numeric=100,'global rule starts exactly at boundary');
select hris_save_payroll_policy(null,'2026-10-10','{"telat_mulai_menit":1,"telat_blok_menit":5,"telat_nominal_per_blok":0,"telat_maks":0,"bolos_per_hari":0,"lembur_per_jam":101}','Fiction same date correction keeps prior version');
select pg_temp.check_it((hris_global_payroll_policy('2026-10-10')->>'lembur_per_jam')::numeric=101,'latest appended same-date correction selected');
select pg_temp.check_it((select count(*)from payroll_policy_versions where group_id is null)=2,'old rule version kept');
select pg_temp.config_deny('select hris_save_payroll_policy(null,''2026-10-11'',''{"telat_mulai_menit":1,"telat_blok_menit":5,"telat_nominal_per_blok":0,"telat_maks":0,"bolos_per_hari":0,"unknown_field":100}'',''Fiction malformed policy'')','missing rate replaced by unknown key');
select hris_add_pay_group_member('92000000-0000-0000-0000-000000000001',id,'2026-10-15','2026-10-20','Fiction dated member')from payroll_policy_groups;
select pg_temp.config_deny(format('select hris_add_pay_group_member(''92000000-0000-0000-0000-000000000001'',%L,''2026-10-20'',''2026-10-21'',''Fiction inclusive overlap'')',(select id from payroll_policy_groups)),'membership endpoints inclusive overlap');
select pg_temp.config_deny(format('select hris_end_pay_group_member(%L,''2026-10-14'',''Fiction invalid end'')',(select id from employee_pay_group_memberships)),'end before group start');
select hris_save_salary_component(null,'2026-10','Fiction monthly meal','tunjangan',500,true,'Fiction confirmed monthly component');
select hris_set_employee_component('92000000-0000-0000-0000-000000000001',id,'2026-10',null,true,'Fiction follows dated master')from salary_components where nama='Fiction monthly meal';
select hris_save_salary_component(id,'2026-11',nama,tipe,650,true,'Fiction next-month change')from salary_components where nama='Fiction monthly meal';
select pg_temp.check_it((select nominal from salary_component_versions where nama='Fiction monthly meal'and effective_period='2026-10')=500,'prior monthly master value preserved');
select hris_set_employee_component('92000000-0000-0000-0000-000000000001',id,'2026-12',null,false,'Fiction next-month benefit end')from salary_components where nama='Fiction monthly meal';
select hris_save_period_component('92000000-0000-0000-0000-000000000001','2026-10','Fiction one-off bonus','tunjangan',50,'Fiction reasoned once only');
select hris_save_period_component('92000000-0000-0000-0000-000000000001','2026-10','Fiction one-off bonus','tunjangan',50,'Fiction repeated submit');
select pg_temp.check_it((select count(*)from payroll_period_components)=1,'repeated named period component does not duplicate payment');
select pg_temp.check_it((select count(*)from hris_payroll_config_events)>=10,'all changes carry immutable actor/reason audit');
select pg_temp.config_deny('update salary_components set nominal=999','raw master bypass');
select pg_temp.config_deny('update employee_salary_components set nominal=999','raw employee component bypass');
select pg_temp.config_deny('update payroll_settings set lembur_per_jam=999','raw policy bypass');
select pg_temp.config_deny('update salary_component_versions set nominal=999','raw version overwrite');
select pg_temp.config_deny('update payroll_period_components set nominal=999','raw variable overwrite');
reset role;
insert into payrolls(employee_id,periode,status,total,source_snapshot)values('92000000-0000-0000-0000-000000000001','2026-10','final',123,'{"fiction_final":"unchanged"}');
create temporary table prior_final as select to_jsonb(p)row from payrolls p;
grant select on prior_final to authenticated;
insert into user_branches(user_id,branch_id,effective_date)values('90000000-0000-0000-0000-000000000003','91000000-0000-0000-0000-000000000001','2026-01-01');
set local role authenticated;
select pg_temp.config_deny('select hris_save_period_component(''92000000-0000-0000-0000-000000000001'',''2026-10'',''Fiction old period'',''tunjangan'',10,''Fiction old change'')','final variable protected');
select pg_temp.config_deny(format('select hris_set_employee_component(''92000000-0000-0000-0000-000000000001'',%L,''2026-10'',999,true,''Fiction old component change'')',(select id from salary_components where nama='Fiction monthly meal')),'final fixed component protected');
select pg_temp.config_deny('select hris_save_payroll_policy(null,''2026-10-21'',''{"telat_mulai_menit":1,"telat_blok_menit":5,"telat_nominal_per_blok":0,"telat_maks":0,"bolos_per_hari":0,"lembur_per_jam":999}'',''Fiction old salary rate'')','final global policy protected');
reset role;
create temporary table prior_group_change as select (select revision from hris_payroll_source_revision)revision,(select count(*)from hris_payroll_config_events)events;
set local role authenticated;
select pg_temp.config_deny(format('select hris_end_pay_group_member(%L,''2026-11-30'',''Fiction extension crosses settled October'')',(select id from employee_pay_group_memberships)),'extension cannot cross finalized month');
select pg_temp.check_it((select valid_to from employee_pay_group_memberships)='2026-10-20'::date,'denied extension leaves membership unchanged');
select pg_temp.config_deny(format('select hris_end_pay_group_member(%L,''2026-10-18'',''Fiction shrink changes settled October'')',(select id from employee_pay_group_memberships)),'shortening cannot change finalized month');
reset role;
select pg_temp.check_it((select revision=(select revision from prior_group_change)from hris_payroll_source_revision),'denied membership changes leave source revision unchanged');
select pg_temp.check_it((select count(*)from hris_payroll_config_events)=(select events from prior_group_change),'denied membership changes leave audit unchanged');
set local role authenticated;
select hris_save_period_component('92000000-0000-0000-0000-000000000001','2026-11','Fiction next period','potongan',10,'Fiction explicit next-month adjustment');
select pg_temp.check_it((select to_jsonb(p)=o.row from payrolls p cross join prior_final o),'future change does not rewrite finalized snapshot');
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000003',true);
select hris_save_period_component('92000000-0000-0000-0000-000000000001','2026-11','Fiction scoped HR','tunjangan',10,'Fiction authorized HR assignment');
select pg_temp.config_deny('select hris_create_pay_group(''Fiction unauthorized group'',''Fiction admin global change'')','global group Owner only');
select pg_temp.config_deny('insert into commission_rules(nama,tipe,persen)values(''Fiction global admin incentive'',''persen'',1)','admin global commission rejected');
insert into commission_rules(nama,tipe,persen,branch_id)values('Fiction scoped incentive','persen',1,'91000000-0000-0000-0000-000000000001');
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000001',true);
select pg_temp.config_deny('select hris_save_period_component(''92000000-0000-0000-0000-000000000001'',''2026-11'',''Fiction staff self bonus'',''tunjangan'',999,''Fiction self approval'')','staff cannot mint own bonus');
select pg_temp.config_deny('insert into commission_rules(nama,tipe,persen)values(''Fiction staff incentive'',''persen'',99)','staff cannot raise financial master rates');
select pg_temp.check_it((select count(*)from employee_salary_component_versions where employee_id='92000000-0000-0000-0000-000000000001')=2,'staff may inspect own fixed history');
select pg_temp.config_deny('select hris_global_payroll_policy(''2026-11-01'')','staff cannot bypass company policy metadata permission');
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000002',true);
select hris_add_pay_group_member('92000000-0000-0000-0000-000000000001',id,'2026-11-01','2026-11-10','Fiction membership after final October')from payroll_policy_groups;
select hris_end_pay_group_member(id,'2026-12-10','Fiction extension entirely after final October')from employee_pay_group_memberships where valid_from='2026-11-01';
select hris_end_pay_group_member(id,'2026-11-30','Fiction shorten December after final October')from employee_pay_group_memberships where valid_from='2026-11-01';
select pg_temp.check_it((select valid_to from employee_pay_group_memberships where valid_from='2026-11-01')='2026-11-30'::date,'future membership extension and shortening allowed');
rollback;
